const config=window.MOMENTRA_CONFIG||{};
const safeUrl=value=>{try{const url=new URL(value);return url.protocol==='https:'||url.protocol==='http:'?url.href:'';}catch{return '';}};
const download=safeUrl(config.downloadUrl),github=safeUrl(config.githubUrl);let toastTimer;
function notify(message){const box=document.getElementById('site-toast');box.textContent=message;box.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>box.hidden=true,4500);}
document.querySelectorAll('[data-download]').forEach(a=>{if(download){a.href=download;a.rel='noopener';}else a.addEventListener('click',()=>{document.getElementById('release-note').textContent='The download link will be added here when the release is ready.';});});
document.querySelectorAll('[data-github]').forEach(a=>{if(github){a.href=github;a.target='_blank';a.rel='noopener noreferrer';a.setAttribute('aria-label','View Momentra on GitHub');}else{a.setAttribute('aria-disabled','true');a.addEventListener('click',e=>{e.preventDefault();notify('The GitHub link is coming soon.');});}});
if(download)document.getElementById('release-note').textContent='Windows portable app · Open it. Make something good.';
const preview=document.getElementById('output-preview');
for(const attribute of ['caption','layout'])document.querySelectorAll('button[data-'+attribute+']').forEach(button=>{button.addEventListener('click',()=>{document.querySelectorAll('button[data-'+attribute+']').forEach(other=>other.setAttribute('aria-pressed',String(button===other)));preview.dataset[attribute]=button.dataset[attribute];if(attribute==='caption')preview.querySelector('.output-caption').innerHTML=button.dataset.caption==='clean'?'Wait for <em>it.</em>':'WAIT FOR <em>IT.</em>';document.getElementById('demo-state').textContent='Your style. Your moment.';});});
const demo=document.getElementById('product-demo'),theme=document.getElementById('demo-theme');
theme.addEventListener('click',()=>{const dark=demo.classList.toggle('demo-dark');theme.querySelector('span').textContent=dark?'Dark':'Light';theme.setAttribute('aria-label','Switch demo to '+(dark?'light':'dark')+' mode');});
let playing=false,frameTimer=null,seconds=728;
function setPlaying(value){playing=value;demo.classList.toggle('is-previewing',value);const play=document.getElementById('demo-play');play.setAttribute('aria-label',value?'Pause illustrative preview':'Play illustrative preview');play.innerHTML=value?'<span style="font-size:10px">Ⅱ</span>':'<svg><use href="#play"/></svg>';clearInterval(frameTimer);if(value)frameTimer=setInterval(()=>{seconds++;if(seconds>760)seconds=728;document.getElementById('demo-time').textContent=Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');document.getElementById('timeline-fill').style.width=(31+(seconds-728)*1.2)+'%';},1000);}
document.getElementById('demo-play').addEventListener('click',()=>setPlaying(!playing));
document.getElementById('demo-render').addEventListener('click',()=>{setPlaying(true);document.getElementById('demo-state').textContent='Sample preview playing · '+({top:'Facecam top',bottom:'Facecam bottom',full:'Full screen'}[preview.dataset.layout]);notify('This is an interactive sample. Download Momentra to make clips from your videos.');});
document.addEventListener('visibilitychange',()=>{if(document.hidden)setPlaying(false);});
const crop=document.getElementById('demo-crop');crop.tabIndex=0;crop.setAttribute('role','group');crop.setAttribute('aria-label','Illustrative facecam crop. Drag to move or use arrow keys.');let drag=null;
crop.addEventListener('pointerdown',e=>{const parent=crop.parentElement.getBoundingClientRect(),box=crop.getBoundingClientRect();drag={x:e.clientX,y:e.clientY,left:box.left-parent.left,top:box.top-parent.top,parent};crop.setPointerCapture(e.pointerId);e.preventDefault();});
crop.addEventListener('pointermove',e=>{if(!drag)return;const left=Math.max(0,Math.min(drag.parent.width-crop.offsetWidth,drag.left+e.clientX-drag.x)),top=Math.max(0,Math.min(drag.parent.height-crop.offsetHeight,drag.top+e.clientY-drag.y));crop.style.left=left/drag.parent.width*100+'%';crop.style.top=top/drag.parent.height*100+'%';});
for(const event of ['pointerup','pointercancel','lostpointercapture'])crop.addEventListener(event,()=>drag=null);
crop.addEventListener('keydown',e=>{if(!e.key.startsWith('Arrow'))return;e.preventDefault();const parent=crop.parentElement.getBoundingClientRect(),box=crop.getBoundingClientRect(),step=e.shiftKey?10:3;crop.style.left=Math.max(0,Math.min(parent.width-box.width,box.left-parent.left+(e.key==='ArrowRight'?step:e.key==='ArrowLeft'?-step:0)))/parent.width*100+'%';crop.style.top=Math.max(0,Math.min(parent.height-box.height,box.top-parent.top+(e.key==='ArrowDown'?step:e.key==='ArrowUp'?-step:0)))/parent.height*100+'%';});
document.querySelectorAll('.waveform').forEach(wave=>{for(let i=0;i<55;i++){const bar=document.createElement('i');bar.style.height=(8+Math.abs(Math.sin(i*1.7)*Math.cos(i*.27))*58)+'px';wave.append(bar);}});
